UPDATE OUTBOX_TBL
SET STATUS = 'PROCESSING',
    PROCESSING_AT = SYSTIMESTAMP

WHERE EVENT_ID = #{eventId}
  AND STATUS = 'PENDING'

  AND NOT EXISTS (
      SELECT 1
      FROM OUTBOX_TBL OTHER
      WHERE OTHER.AGGREGATE_ID = (
          SELECT TARGET.AGGREGATE_ID
          FROM OUTBOX_TBL TARGET
          WHERE TARGET.EVENT_ID = #{eventId}
      )
        AND OTHER.EVENT_ID <> #{eventId}
        AND OTHER.STATUS = 'PROCESSING'
  )
